<?php require_once __DIR__.'/../config/auth.php';require_role('boss');$pdo=db();$branch=(int)($_GET['branch']??0);$sql='SELECT b.name branch,p.name,p.stock,p.min_stock,p.purchase_price,(p.stock*p.purchase_price) value FROM products p JOIN branches b ON b.id=p.branch_id WHERE p.is_active=1';$args=[];if($branch){$sql.=' AND p.branch_id=?';$args[]=$branch;}$sql.=' ORDER BY (p.stock<=p.min_stock) DESC,b.name,p.name';$s=$pdo->prepare($sql);$s->execute($args);$rows=$s->fetchAll();$branches=$pdo->query('SELECT id,name FROM branches ORDER BY name')->fetchAll();$pageTitle='Stok Semua Cabang';$active='stok';include __DIR__.'/../includes/header.php';?><section class="card"><form class="filter-row"><label>Cabang<select name="branch"><option value="0">Semua cabang</option><?php foreach($branches as $b):?><option value="<?=$b['id']?>" <?=$branch===$b['id']?'selected':''?>><?=e($b['name'])?></option><?php endforeach;?></select></label><button class="btn primary">Tampilkan</button></form><div class="table-wrap"><table class="table"><thead><tr><th>Cabang</th><th>Produk</th><th>Stok</th><th>Status</th><th>Nilai modal</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['branch'])?></td><td><?=e($r['name'])?></td><td><?=$r['stock']?></td><td><span class="badge <?=$r['stock']<=$r['min_stock']?'warn':''?>"><?=$r['stock']==0?'Habis':($r['stock']<=$r['min_stock']?'Menipis':'Aman')?></span></td><td><?=rupiah($r['value'])?></td></tr><?php endforeach;?></tbody></table><?php if(!$rows):?><div class="empty-state">Belum ada produk.</div><?php endif;?></div></section><?php include __DIR__.'/../includes/footer.php';?>
